-- 股票分析系统数据库导出
-- 导出时间: 2026-07-31 17:19:27
-- 共 9 张表, 47475 行数据
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `stock_info`;
CREATE TABLE `stock_info` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(20) NOT NULL,
  `stock_name` varchar(100) NOT NULL,
  `market` varchar(10) NOT NULL COMMENT '市场: SH=上海, SZ=深圳',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_stock_info_stock_code` (`stock_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5535 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `stock_core_data`;
CREATE TABLE `stock_core_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(20) NOT NULL,
  `stock_name` varchar(100) DEFAULT NULL,
  `market` varchar(10) DEFAULT NULL,
  `total_market_cap` decimal(24,4) DEFAULT NULL,
  `float_market_cap` decimal(24,4) DEFAULT NULL,
  `eps` decimal(24,4) DEFAULT NULL,
  `pe_dynamic` decimal(24,4) DEFAULT NULL,
  `navps` decimal(24,4) DEFAULT NULL,
  `pb` decimal(24,4) DEFAULT NULL,
  `revenue` decimal(24,4) DEFAULT NULL,
  `revenue_yoy` decimal(24,4) DEFAULT NULL,
  `net_profit` decimal(24,4) DEFAULT NULL,
  `profit_yoy` decimal(24,4) DEFAULT NULL,
  `gross_margin` decimal(24,4) DEFAULT NULL,
  `net_margin` decimal(24,4) DEFAULT NULL,
  `roe` decimal(24,4) DEFAULT NULL,
  `debt_ratio` decimal(24,4) DEFAULT NULL,
  `total_shares` decimal(24,4) DEFAULT NULL,
  `float_shares` decimal(24,4) DEFAULT NULL,
  `retained_eps` decimal(24,4) DEFAULT NULL,
  `list_date` varchar(20) DEFAULT NULL,
  `change_pct` decimal(24,4) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `last_sync_time` datetime DEFAULT NULL COMMENT '最近一次行情同步时间',
  `data_source_type` varchar(20) DEFAULT NULL COMMENT '同步时使用的数据源',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stock_core_code` (`stock_code`),
  UNIQUE KEY `ix_stock_core_data_stock_code` (`stock_code`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `stock_dividend_events`;
CREATE TABLE `stock_dividend_events` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `stock_code` varchar(20) NOT NULL COMMENT '股票代码',
  `event_name` varchar(50) DEFAULT NULL COMMENT '事件名称（如 2024年末期）',
  `record_date` date DEFAULT NULL COMMENT '股权登记日',
  `ex_dividend_date` date NOT NULL COMMENT '除权除息日',
  `payment_date` date DEFAULT NULL COMMENT '派息日/到账日',
  `cash_per_10` decimal(12,6) DEFAULT '0.000000' COMMENT '每10股派现金（含税）',
  `bonus_per_10` decimal(12,6) DEFAULT '0.000000' COMMENT '每10股送股数',
  `conversion_per_10` decimal(12,6) DEFAULT '0.000000' COMMENT '每10股转增股数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '入库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_stock_exdiv` (`stock_code`,`ex_dividend_date`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='股票分红送转事件表';


DROP TABLE IF EXISTS `stock_cookies`;
CREATE TABLE `stock_cookies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cookie` varchar(4096) NOT NULL,
  `fail_count` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `simulation_account`;
CREATE TABLE `simulation_account` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `initial_cash` decimal(18,2) NOT NULL,
  `cash` decimal(18,2) NOT NULL,
  `commission_rate` decimal(8,6) NOT NULL COMMENT '佣金费率（如 0.0003=万分之三）',
  `min_commission` decimal(10,2) NOT NULL COMMENT '最低佣金（元）',
  `stamp_tax_rate` decimal(8,6) NOT NULL COMMENT '印花税率（卖出时收取，0.0005=万分之五）',
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `simulation_position`;
CREATE TABLE `simulation_position` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_id` int NOT NULL,
  `stock_code` varchar(20) NOT NULL,
  `stock_name` varchar(100) DEFAULT NULL,
  `shares` int NOT NULL COMMENT '持仓股数',
  `avg_cost` decimal(12,4) NOT NULL COMMENT '平均成本价',
  `total_cost` decimal(18,2) NOT NULL COMMENT '总成本（含买入费用）',
  `current_price` decimal(12,4) DEFAULT NULL COMMENT '最新市价',
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_position_account_stock` (`account_id`,`stock_code`),
  KEY `ix_simulation_position_account_id` (`account_id`),
  KEY `ix_simulation_position_stock_code` (`stock_code`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `simulation_trade`;
CREATE TABLE `simulation_trade` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_id` int NOT NULL,
  `stock_code` varchar(20) NOT NULL,
  `stock_name` varchar(100) DEFAULT NULL,
  `trade_type` varchar(10) NOT NULL COMMENT 'buy / sell',
  `shares` int NOT NULL,
  `price` decimal(12,4) NOT NULL COMMENT '成交价',
  `amount` decimal(18,2) NOT NULL COMMENT '成交金额',
  `commission` decimal(12,2) NOT NULL COMMENT '佣金',
  `stamp_tax` decimal(12,2) NOT NULL COMMENT '印花税',
  `profit_loss` decimal(18,2) DEFAULT NULL COMMENT '卖出时的盈亏',
  `profit_loss_pct` decimal(12,4) DEFAULT NULL COMMENT '卖出时的盈亏比例(%)',
  `trade_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_simulation_trade_stock_code` (`stock_code`),
  KEY `ix_simulation_trade_account_id` (`account_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `stock_weekday_stats`;
CREATE TABLE `stock_weekday_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(20) NOT NULL,
  `weekday` varchar(10) NOT NULL COMMENT '星期几: 星期一~星期五',
  `total_count` int NOT NULL COMMENT '该星期几的交易日总数',
  `up_count` int NOT NULL COMMENT '上涨天数',
  `down_count` int NOT NULL COMMENT '下跌天数',
  `flat_count` int NOT NULL COMMENT '平盘天数',
  `up_pct` decimal(8,4) NOT NULL COMMENT '上涨概率(%)',
  `down_pct` decimal(8,4) NOT NULL COMMENT '下跌概率(%)',
  `mean_change` decimal(12,6) NOT NULL COMMENT '平均涨跌幅(%)',
  `median_change` decimal(12,6) DEFAULT NULL COMMENT '中位数涨跌幅(%)',
  `std_change` decimal(12,6) DEFAULT NULL COMMENT '涨跌幅标准差',
  `max_gain` decimal(12,6) DEFAULT NULL COMMENT '最大涨幅(%)',
  `max_loss` decimal(12,6) DEFAULT NULL COMMENT '最大跌幅(%)',
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stock_weekday` (`stock_code`,`weekday`),
  KEY `ix_stock_weekday_stats_stock_code` (`stock_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `stock_daily_quote`;
CREATE TABLE `stock_daily_quote` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `stock_code` varchar(20) NOT NULL COMMENT '股票代码，如601857',
  `trade_date` date NOT NULL COMMENT '交易日期',
  `open_price` decimal(12,4) NOT NULL COMMENT '开盘价（不复权）',
  `high_price` decimal(12,4) NOT NULL COMMENT '最高价（不复权）',
  `low_price` decimal(12,4) NOT NULL COMMENT '最低价（不复权）',
  `close_price` decimal(12,4) NOT NULL COMMENT '收盘价（不复权）',
  `volume` bigint NOT NULL COMMENT '成交量（股）',
  `amount` decimal(20,4) NOT NULL COMMENT '成交额（元）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '入库时间',
  `forward_open` decimal(12,4) DEFAULT NULL,
  `forward_high` decimal(12,4) DEFAULT NULL,
  `forward_low` decimal(12,4) DEFAULT NULL,
  `forward_close` decimal(12,4) DEFAULT NULL,
  `backward_open` decimal(12,4) DEFAULT NULL,
  `backward_high` decimal(12,4) DEFAULT NULL,
  `backward_low` decimal(12,4) DEFAULT NULL,
  `backward_close` decimal(12,4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_stock_date` (`stock_code`,`trade_date`)
) ENGINE=InnoDB AUTO_INCREMENT=41891 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='股票日线行情（不复权）';


